package com.gameaggregator.deploymentservice.application;import static org.assertj.core.api.Assertions.assertThat;import com.gameaggregator.deploymentservice.domain.DeploymentStatus;import org.junit.jupiter.api.Test;class DeploymentStateMachineTest{@Test void successCanOnlyRollback(){assertThat(DeploymentService.ALLOWED.get(DeploymentStatus.SUCCEEDED)).containsExactly(DeploymentStatus.ROLLED_BACK);}@Test void terminalStatesCannotTransition(){assertThat(DeploymentService.ALLOWED.get(DeploymentStatus.CANCELLED)).isEmpty();assertThat(DeploymentService.ALLOWED.get(DeploymentStatus.ROLLED_BACK)).isEmpty();}@Test void normalPathIsDefined(){assertThat(DeploymentService.ALLOWED.get(DeploymentStatus.PENDING)).contains(DeploymentStatus.QUEUED);assertThat(DeploymentService.ALLOWED.get(DeploymentStatus.QUEUED)).contains(DeploymentStatus.RUNNING);assertThat(DeploymentService.ALLOWED.get(DeploymentStatus.RUNNING)).contains(DeploymentStatus.SUCCEEDED,DeploymentStatus.FAILED);}}